{"content":"import { defineComponents, Type, type ComponentDefinition } from '@iwsdk/core';

// Forge item states
export enum ForgeItemState {
	IDLE = 0,
	HEATING = 1,
	HOT = 2,
	HAMMERING = 3,
	HAMMERED = 4,
	QUENCHING = 5,
	QUENCHED = 6,
	READY = 7,
}

// Metal types
export enum MetalType {
	IRON = 0,
	STEEL = 1,
	MITHRIL = 2,
}

// Item types
export enum ItemType {
	SWORD = 0,
	AXE = 1,
	SHIELD = 2,
	DAGGER = 3,
	HELMET = 4,
}

export const ForgeItem: ComponentDefinition = {
	state: { type: Type.Number, default: ForgeItemState.IDLE },
	metalType: { type: Type.Number, default: MetalType.IRON },
	itemType: { type: Type.Number, default: ItemType.SWORD },
	heatLevel: { type: Type.Number, default: 0 },
	hammerCount: { type: Type.Number, default: 0 },
	hammerTarget: { type: Type.Number, default: 5 },
	isActive: { type: Type.Boolean, default: false },
};

export default defineComponents([ForgeItem]);
